#[inductive(combiner_send_skip)]
fn combiner_send_skip_inductive(pre: Self, post: Self) {
    // Proof that not_waiting_inv still holds
    assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() 
    implies !post.slots.index(i) by {
        assert(pre.valid_idx(i));
        assert(pre.clients.index(i).is_Idle() ==> !pre.slots.index(i)); // by invariant

        // Case analysis: is i the slot j that was processed?
        let j = pre.combiner.get_Responding_idx();
        if i == j {
            // Slot j had response_opt = None, meaning no request was stored there
            // Since client i is Idle, slot should remain false (no change in this case)
            // But actually, the transition doesn't change the slot for skip operation
            assert(post.slots.index(i) == pre.slots.index(i));
            assert(!pre.slots.index(i));
        } else {
            // Slot remains unchanged
            assert(post.slots.index(i) == pre.slots.index(i));
            assert(!pre.slots.index(i));
        }
    }

    // Proof that waiting_inv still holds
    assert forall |i: nat| #[trigger] post.client_waiting(i) 
    implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
        assert(pre.client_waiting(i));
        assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i)); // by invariant

        // Case analysis: relationship to slot j that was processed
        let j = pre.combiner.get_Responding_idx();
        if i < j {
            // This client was already processed, nothing changes for it
            assert(post.request_stored(i) == pre.request_stored(i));
            assert(post.response_stored(i) == pre.response_stored(i));
            assert(post.combiner_has(i) == pre.combiner_has(i));
        } else if i > j {
            // This client hasn't been processed yet
            // With the index incremented, the definition of combiner_has changes for i
            // pre.combiner_has(i) meant i >= j && elems[i].is_Some()
            // post.combiner_has(i) means i >= (j+1) && elems[i].is_Some()
            // So if i > j, condition becomes stricter
            assert(post.combiner_has(i) ==> pre.combiner_has(i));
            if post.combiner_has(i) {
                assert(pre.combiner_has(i));
            }
            // Values remain unchanged
            assert(post.request_stored(i) == pre.request_stored(i));
            assert(post.response_stored(i) == pre.response_stored(i));
        } else {
            // i == j, this is the slot that was skipped
            // response_opt was None, so !pre.combiner_has(j)
            // After incrementing index:
            // post.combiner_has(j) would mean j >= (j+1) && elems[j].is_Some(), which is false since j >= j+1 is false
            assert(!post.combiner_has(j));
            // Other values remain unchanged
            assert(post.request_stored(j) == pre.request_stored(j));
            assert(post.response_stored(j) == pre.response_stored(j));
        }

        // Therefore the disjunction still holds
        assert(post.request_stored(i) || post.response_stored(i) || post.combiner_has(i));
    }

    // Proof that request_stored_inv still holds
    assert forall |i: nat| #[trigger] post.request_stored(i)
    implies post.client_waiting(i) 
        && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && post.slots.index(i) by {
        assert(pre.request_stored(i));
        // By pre invariant:
        assert(pre.client_waiting(i));
        assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
        assert(pre.slots.index(i));

        // Check if anything changed for index i
        let j = pre.combiner.get_Responding_idx();
        if i == j {
            // This index was skipped, but nothing should have changed the request storage
            assert(post.requests.index(i).rid == pre.requests.index(i).rid);
            assert(post.clients.index(i).get_Waiting_rid() == pre.clients.index(i).get_Waiting_rid());
            assert(post.slots.index(i) == pre.slots.index(i));
            assert(post.client_waiting(i) == pre.client_waiting(i));
        } else {
            // No changes to this index
            assert(post.requests.index(i).rid == pre.requests.index(i).rid);
            assert(post.clients.index(i).get_Waiting_rid() == pre.clients.index(i).get_Waiting_rid());
            assert(post.slots.index(i) == pre.slots.index(i));
            assert(post.client_waiting(i) == pre.client_waiting(i));
        }
    }

    // Proof that response_stored_inv still holds
    assert forall |i: nat| #[trigger] post.response_stored(i)
    implies post.client_waiting(i)
        && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && !post.slots.index(i) by {
        assert(pre.response_stored(i));
        // By pre invariant:
        assert(pre.client_waiting(i));
        assert(pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid());
        assert(!pre.slots.index(i));

        // The skip operation doesn't add responses, so if something is stored now,
        // it was already stored before
        assert(post.responses.index(i).rid == pre.responses.index(i).rid);
        assert(post.clients.index(i).get_Waiting_rid() == pre.clients.index(i).get_Waiting_rid());
        assert(post.slots.index(i) == pre.slots.index(i));
        assert(post.client_waiting(i) == pre.client_waiting(i));
    }
}

